import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { z } from "zod";
import { chromium } from "playwright";
import { readFileSync, existsSync, readdirSync } from "fs";
import { join, dirname } from "path";
import { fileURLToPath } from "url";

const __dirname = dirname(fileURLToPath(import.meta.url));

// Load data files — generated by scripts/parse-tokens.js and static emag.json
const DATA_DIR    = join(__dirname, "data");
const DS_CORE_DIR = join(__dirname, "../app/node_modules/@govbr-ds/core/dist/components");

function loadJson(filename, fallback) {
  const path = join(DATA_DIR, filename);
  if (!existsSync(path)) {
    console.error(`[govbr-ds] Warning: ${filename} not found. Run scripts/parse-tokens.js to generate it.`);
    return fallback;
  }
  return JSON.parse(readFileSync(path, "utf8"));
}

const TOKENS     = loadJson("tokens.json", null);
const EMAG       = loadJson("emag.json", null);
const PAGE_RULES = loadJson("ds-page-rules.json", null);

// ─────────────────────────────────────────────────────────────────────────────
// govbr-ds MCP server — DS knowledge layer
//
// What this server is NOT:
//   - A browser automation tool (use @playwright/mcp for that)
//   - A rule engine that returns verdicts (the agent reasons)
//
// What this server IS:
//   - The gov.br DS token reference (what values are valid)
//   - The e-MAG accessibility rules (Brazilian gov standard, not in axe-core)
//   - A computed CSS inspector (the one thing @playwright/mcp doesn't expose)
// ─────────────────────────────────────────────────────────────────────────────

const server = new McpServer({
  name: "govbr-ds",
  version: "1.0.0",
});

// ── Tool 1: Design tokens ─────────────────────────────────────────────────────

server.tool(
  "get_design_tokens",
  "Returns the gov.br Design System (Padrão Digital de Governo) token reference parsed from the installed @govbr-ds/core npm package. Includes all color, typography, spacing, and surface tokens plus a hex→token reverse lookup. Run scripts/parse-tokens.js to regenerate after upgrading the DS package.",
  {
    query: z.string().optional().describe("Filter tokens by name fragment (e.g. 'blue', 'spacing', 'font'). Omit for semantic highlights only."),
  },
  async ({ query }) => {
    if (!TOKENS) {
      return { content: [{ type: "text", text: "Token data not loaded. Run: node scripts/parse-tokens.js" }] };
    }
    // Without query: return semantic highlights + hex lookup (most useful for validation)
    if (!query) {
      return { content: [{ type: "text", text: JSON.stringify({ meta: TOKENS.meta, semantic: TOKENS.semantic, hexLookup: TOKENS.hexLookup }, null, 2) }] };
    }
    // With query: filter matching tokens from the full set
    const q = query.toLowerCase();
    const matches = Object.fromEntries(
      Object.entries(TOKENS.all ?? {}).filter(([k]) => k.toLowerCase().includes(q))
    );
    return { content: [{ type: "text", text: JSON.stringify({ query, count: Object.keys(matches).length, tokens: matches }, null, 2) }] };
  }
);

// ── Tool 2: e-MAG rules ───────────────────────────────────────────────────────

server.tool(
  "get_emag_rules",
  "Returns the complete e-MAG v3.1 (Modelo de Acessibilidade em Governo Eletrônico) — all 6 sections, all rules with IDs, descriptions, and WCAG mappings. This is the Brazilian government accessibility standard, mandatory for all gov.br portals. Not covered by generic tools like axe-core.",
  {
    section: z.number().min(1).max(6).optional().describe("Return only a specific section (1–6). Omit for all sections."),
  },
  async ({ section }) => {
    if (!EMAG) {
      return { content: [{ type: "text", text: "e-MAG data not loaded. Check mcp-server/data/emag.json exists." }] };
    }
    const data = section
      ? { meta: EMAG.meta, section: EMAG.sections[String(section)] ?? `Section ${section} not found` }
      : EMAG;
    return { content: [{ type: "text", text: JSON.stringify(data, null, 2) }] };
  }
);

// ── Tool 3: Computed CSS inspector ────────────────────────────────────────────
// @playwright/mcp exposes the accessibility tree but not computed CSS values.
// This tool fills that gap — it launches a headless browser, queries elements,
// and returns their computed styles for the agent to reason about.

server.tool(
  "inspect_computed_styles",
  "Launches a headless browser, finds all interactive elements on the page, and returns their computed CSS values (background-color, font-family, font-size, border-radius, color, etc.) plus focus-state styles (outline, box-shadow while :focus is active). Use this alongside @playwright/mcp's browser_snapshot to get both accessibility AND visual token data.",
  {
    url: z.string().url().describe("URL of the page to inspect"),
    selector: z.string().optional().describe("CSS selector to narrow inspection (default: all interactive elements)"),
  },
  async ({ url, selector }) => {
    const browser = await chromium.launch({ headless: true });
    const page = await browser.newPage();

    try {
      await page.goto(url, { waitUntil: "networkidle" });

      const target = selector ?? "button, a, input, select, textarea, [role='button'], [role='link'], [role='checkbox'], [role='radio']";

      const elements = await page.evaluate((sel) => {
        return Array.from(document.querySelectorAll(sel)).map((el) => {
          const computed = window.getComputedStyle(el);

          // Capture focus-state styles by briefly focusing the element
          el.focus({ preventScroll: true });
          const focusedComputed = window.getComputedStyle(el);
          const focusedStyles = {
            outline:       focusedComputed.outline,
            outlineColor:  focusedComputed.outlineColor,
            outlineWidth:  focusedComputed.outlineWidth,
            outlineStyle:  focusedComputed.outlineStyle,
            outlineOffset: focusedComputed.outlineOffset,
            boxShadow:     focusedComputed.boxShadow,
          };
          el.blur();

          return {
            tagName: el.tagName,
            id: el.id || null,
            classes: Array.from(el.classList),
            testId: el.closest("[data-testid]")?.getAttribute("data-testid") ?? null,
            attributes: {
              type:          el.getAttribute("type"),
              role:          el.getAttribute("role"),
              ariaLabel:     el.getAttribute("aria-label"),
              ariaRequired:  el.getAttribute("aria-required"),
              ariaDisabled:  el.getAttribute("aria-disabled"),
              ariaDescribedby: el.getAttribute("aria-describedby"),
              disabled:      el.hasAttribute("disabled"),
              required:      el.hasAttribute("required"),
              htmlFor:       el.getAttribute("for") ?? null,
              placeholder:   el.getAttribute("placeholder") ?? null,
            },
            content: {
              textContent:   el.textContent?.trim().slice(0, 100) ?? "",
              hasVisibleText: (el.textContent?.trim().length ?? 0) > 0,
              hasIconOnly:   !el.textContent?.trim() && el.querySelector("i, svg") !== null,
            },
            inlineStyle: el.getAttribute("style") ?? null,
            computed: {
              backgroundColor: computed.backgroundColor,
              color:           computed.color,
              fontFamily:      computed.fontFamily,
              fontSize:        computed.fontSize,
              fontWeight:      computed.fontWeight,
              lineHeight:      computed.lineHeight,
              borderRadius:    computed.borderRadius,
              border:          computed.border,
              padding:         computed.padding,
              outline:         computed.outline,
              cursor:          computed.cursor,
              opacity:         computed.opacity,
            },
            focusedComputed: focusedStyles,
            outerHTML: el.outerHTML.slice(0, 500),
          };
        });
      }, target);

      return {
        content: [{
          type: "text",
          text: JSON.stringify({ url, selector: target, count: elements.length, elements }, null, 2),
        }],
      };
    } finally {
      await browser.close();
    }
  }
);

// ── Tool 4: DS page/structural rules ─────────────────────────────────────────

server.tool(
  "get_page_rules",
  "Returns gov.br Design System structural guidelines scraped from the official docs — page anatomy, form patterns, navigation do/don'ts, grid usage, HTML best practices, WAI-ARIA rules, and more. Generated by scripts/scrape-ds-rules.js. Use this to validate page-level structure, not individual components.",
  {
    category: z.enum([
      "page_structure",
      "form_patterns",
      "navigation_patterns",
      "help_communication",
      "empty_states",
      "states",
      "grid",
      "writing_principles",
      "microcopy",
      "html_best_practices",
      "html_accessibility",
      "wai_aria",
      "minimum_standard",
    ]).optional().describe("Return only a specific category. Omit to list available categories and metadata."),
  },
  async ({ category }) => {
    if (!PAGE_RULES) {
      return { content: [{ type: "text", text: "Page rules not generated yet. Run: npm run scrape-rules" }] };
    }
    if (!category) {
      const overview = {
        meta: PAGE_RULES.meta,
        available: Object.entries(PAGE_RULES.categories).map(([key, { label, url }]) => ({ key, label, url })),
      };
      return { content: [{ type: "text", text: JSON.stringify(overview, null, 2) }] };
    }
    const data = PAGE_RULES.categories[category];
    if (!data) {
      return { content: [{ type: "text", text: `Category '${category}' not found.` }] };
    }
    return { content: [{ type: "text", text: JSON.stringify(data, null, 2) }] };
  }
);

// ── Tool 5: DS component examples ────────────────────────────────────────────
// The @govbr-ds/core package ships examples.html for every component — these
// are the canonical reference for correct element, class, and ARIA usage.
// Reading them directly means the rules are always in sync with the installed
// DS version, no manual maintenance needed.

server.tool(
  "get_component_examples",
  "Returns the official gov.br DS HTML examples for a component straight from the installed @govbr-ds/core package. Use this to check the canonical element structure, required classes, and ARIA patterns the DS expects (e.g. that circle buttons need aria-label, that br-button must be a <button> element, etc.).",
  {
    component: z.string().describe("Component name, e.g. 'button', 'input', 'select', 'checkbox'. Omit to list all available components.").optional(),
  },
  async ({ component }) => {
    if (!existsSync(DS_CORE_DIR)) {
      return { content: [{ type: "text", text: "DS core not found. Run: cd app && npm install" }] };
    }

    if (!component) {
      const available = readdirSync(DS_CORE_DIR, { withFileTypes: true })
        .filter(d => d.isDirectory())
        .map(d => d.name);
      return { content: [{ type: "text", text: JSON.stringify({ available }, null, 2) }] };
    }

    const examplesPath = join(DS_CORE_DIR, component, "examples.html");
    if (!existsSync(examplesPath)) {
      const available = readdirSync(DS_CORE_DIR, { withFileTypes: true })
        .filter(d => d.isDirectory()).map(d => d.name);
      return { content: [{ type: "text", text: `Component '${component}' not found. Available: ${available.join(", ")}` }] };
    }

    const html = readFileSync(examplesPath, "utf8");
    return { content: [{ type: "text", text: html }] };
  }
);

const transport = new StdioServerTransport();
await server.connect(transport);
